// Seed a template + a list of recipients. One recipient per item.
const template = 'Hi {{name}}, your {{plan}} plan renews on {{date}}. Thanks for being with us since {{year}}!';
const recipients = [
  { name: 'Ada',   plan: 'Pro',        date: '2026-07-01', year: 2021 },
  { name: 'Linus', plan: 'Team',       date: '2026-06-15', year: 2019 },
  { name: 'Grace', plan: 'Enterprise', date: '2026-08-30', year: 2018 }
];
return recipients.map((r) => ({ json: { template, ...r } }));

// Render {{placeholders}} for each recipient. Pure string compute.
const item = $input.item.json;
const tpl = String(item.template || '');
const missing = [];
const rendered = tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  if (item[key] === undefined) { missing.push(key); return m; }
  return String(item[key]);
});
return { json: { name: item.name, rendered, missingVars: missing, length: rendered.length } };
